-----------------------
---- LOOK AND FEEL ----
-----------------------

-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
	general = {
		gaps_in = 0,
		gaps_out = 0,
		border_size = 2,
		col = {
			active_border = "#93a1a1",
			inactive_border = "#38464b",
		},
		resize_on_border = false,
		allow_tearing = false,
		layout = "master",
	},

	decoration = {
		shadow = { enabled = false },
		blur = { enabled = false },
	},

	animations = { enabled = false },
})

-- Ref https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/
-- "Smart gaps" / "No gaps when only"
-- uncomment all if you wish to use that.
-- hl.workspace_rule({ workspace = "w[tv1]", gaps_out = 0, gaps_in = 0 })
-- hl.workspace_rule({ workspace = "f[1]",   gaps_out = 0, gaps_in = 0 })
hl.window_rule({
	name = "no-gaps-wtv1",
	match = { float = false, workspace = "w[tv1]" },
	border_size = 0,
	rounding = 0,
})
-- hl.window_rule({
--     name  = "no-gaps-f1",
--     match = { float = false, workspace = "f[1]" },
--     border_size = 0,
--     rounding    = 0,
-- })

hl.window_rule({
	name = "Calculator",
	match = { class = "qalculate-gtk|io.github.Qalculate.qalculate-qt|org.gnome.Calculator" },
	float = true,
})

-- See https://wiki.hypr.land/Configuring/Layouts/Dwindle-Layout/ for more
hl.config({
	dwindle = { preserve_split = true },
})

-- See https://wiki.hypr.land/Configuring/Layouts/Master-Layout/ for more
hl.config({
	master = {
		mfact = 0.6,
		new_status = "slave",
		new_on_top = true,
	},
})

----------------
----  MISC  ----
----------------

hl.config({
	binds = { movefocus_cycles_fullscreen = true },
	misc = { force_default_wallpaper = 0 },
})

---------------
---- INPUT ----
---------------

hl.config({
	input = {
		kb_layout = "us",
		kb_variant = "altgr-intl",
		kb_model = "",
		kb_options = "caps:ctrl_modifier",
		kb_rules = "",

		repeat_delay = 300,
		repeat_rate = 50,

		follow_mouse = 1,

		sensitivity = 0, -- -1.0 - 1.0, 0 means no modification.

		touchpad = {
			drag_lock = true,
			natural_scroll = false,
		},
	},
})

hl.gesture({
	fingers = 3,
	direction = "horizontal",
	action = "workspace",
})

-- Example per-device config
-- See https://wiki.hypr.land/Configuring/Advanced-and-Cool/Devices/ for more
hl.device({
	name = "epic-mouse-v1",
	sensitivity = -0.5,
})

---------------------
---- KEYBINDINGS ----
---------------------

-- see https://wiki.hypr.land/Configuring/Basics/Binds/ for more

hl.bind("SUPER + Return", hl.dsp.exec_cmd("alacritty"))
hl.bind("SUPER + Space", hl.dsp.exec_cmd("bemenu-run"))
hl.bind("SUPER + SHIFT + Space", hl.dsp.exec_cmd("myshell run_term"))
hl.bind("SUPER + Delete", hl.dsp.exec_cmd("loginctl lock-session"))
hl.bind("SUPER + SHIFT + Delete", hl.dsp.exec_cmd("uwsm stop"))

hl.bind("SUPER + Q", hl.dsp.window.close())
hl.bind("SUPER + F", hl.dsp.window.fullscreen({ action = "toggle" }))
hl.bind("SUPER + T", hl.dsp.window.float({ action = "toggle" }))

hl.bind("SUPER + H", hl.dsp.focus({ direction = "left" }))
hl.bind("SUPER + L", hl.dsp.focus({ direction = "right" }))
hl.bind("SUPER + K", hl.dsp.focus({ direction = "up" }))
hl.bind("SUPER + J", hl.dsp.focus({ direction = "down" }))

hl.bind("SUPER + SHIFT + H", hl.dsp.window.move({ direction = "left" }))
hl.bind("SUPER + SHIFT + L", hl.dsp.window.move({ direction = "right" }))
hl.bind("SUPER + SHIFT + K", hl.dsp.window.move({ direction = "up" }))
hl.bind("SUPER + SHIFT + J", hl.dsp.window.move({ direction = "down" }))

hl.bind("SUPER + I", hl.dsp.focus({ monitor = "-1" }))
hl.bind("SUPER + O", hl.dsp.focus({ monitor = "+1" }))
hl.bind("SUPER + P", hl.dsp.workspace.move({ monitor = "+1" }))

hl.bind("SUPER + SHIFT + I", hl.dsp.window.move({ monitor = "-1" }))
hl.bind("SUPER + SHIFT + O", hl.dsp.window.move({ monitor = "+1" }))

hl.bind("SUPER + Minus", hl.dsp.window.resize({ x = 0, y = -100, relative = true }))
hl.bind("SUPER + Equal", hl.dsp.window.resize({ x = 0, y = 100, relative = true }))

hl.bind("SUPER + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind("SUPER + mouse:273", hl.dsp.window.resize(), { mouse = true })
hl.bind("SUPER + mouse:274", hl.dsp.window.float({ action = "toggle" }), { mouse = true })

hl.bind("SUPER + M", hl.dsp.layout("swapwithmaster master"))
hl.bind("SUPER + BracketLeft", hl.dsp.layout("mfact -0.05"))
hl.bind("SUPER + BracketRight", hl.dsp.layout("mfact +0.05"))
hl.bind("SUPER + SHIFT + Bracketleft", hl.dsp.layout("addmaster"))
hl.bind("SUPER + SHIFT + Bracketright", hl.dsp.layout("removemaster"))

hl.bind("SUPER + Up", hl.dsp.layout("orientationtop"))
hl.bind("SUPER + Down", hl.dsp.layout("orientationcenter"))
hl.bind("SUPER + Left", hl.dsp.layout("orientationleft"))
hl.bind("SUPER + Right", hl.dsp.layout("orientationright"))

hl.bind("SUPER + 1", hl.dsp.focus({ workspace = 1 }))
hl.bind("SUPER + 2", hl.dsp.focus({ workspace = 2 }))
hl.bind("SUPER + 3", hl.dsp.focus({ workspace = 3 }))
hl.bind("SUPER + 4", hl.dsp.focus({ workspace = 4 }))
hl.bind("SUPER + 5", hl.dsp.focus({ workspace = 5 }))
hl.bind("SUPER + 6", hl.dsp.focus({ workspace = 6 }))
hl.bind("SUPER + 7", hl.dsp.focus({ workspace = 7 }))
hl.bind("SUPER + 8", hl.dsp.focus({ workspace = 8 }))
hl.bind("SUPER + 9", hl.dsp.focus({ workspace = 9 }))
hl.bind("SUPER + 0", hl.dsp.focus({ workspace = 10 }))
hl.bind("SUPER + N", hl.dsp.workspace.toggle_special("notes"))

hl.bind("SUPER + SHIFT + 1", hl.dsp.window.move({ workspace = 1, follow = false }))
hl.bind("SUPER + SHIFT + 2", hl.dsp.window.move({ workspace = 2, follow = false }))
hl.bind("SUPER + SHIFT + 3", hl.dsp.window.move({ workspace = 3, follow = false }))
hl.bind("SUPER + SHIFT + 4", hl.dsp.window.move({ workspace = 4, follow = false }))
hl.bind("SUPER + SHIFT + 5", hl.dsp.window.move({ workspace = 5, follow = false }))
hl.bind("SUPER + SHIFT + 6", hl.dsp.window.move({ workspace = 6, follow = false }))
hl.bind("SUPER + SHIFT + 7", hl.dsp.window.move({ workspace = 7, follow = false }))
hl.bind("SUPER + SHIFT + 8", hl.dsp.window.move({ workspace = 8, follow = false }))
hl.bind("SUPER + SHIFT + 9", hl.dsp.window.move({ workspace = 9, follow = false }))
hl.bind("SUPER + SHIFT + 0", hl.dsp.window.move({ workspace = 10, follow = false }))
hl.bind("SUPER + SHIFT + N", hl.dsp.window.move({ workspace = "special:notes", follow = false }))

hl.bind("SUPER + Tab", hl.dsp.focus({ workspace = "previous_per_monitor" }))

hl.bind("SUPER + E", hl.dsp.exec_cmd("myshell files"))
hl.bind("SUPER + SHIFT + E", hl.dsp.exec_cmd("exo-open ~/Downloads"))
hl.bind("SUPER + C", hl.dsp.exec_cmd("myshell calc"))
hl.bind("SUPER + Backslash", hl.dsp.exec_cmd("myshell find"))
hl.bind("SUPER + SHIFT + Backslash", hl.dsp.exec_cmd("myshell find /"))

hl.bind("SUPER + Y", hl.dsp.exec_cmd("myshell notify_menu"))
hl.bind("SUPER + U", hl.dsp.exec_cmd("myshell notify_dismiss"))
hl.bind("SUPER + SHIFT + U", hl.dsp.exec_cmd("myshell notify_restore"))

hl.bind("SUPER + Period", hl.dsp.exec_cmd("myshell emoji"))

hl.bind("Print", hl.dsp.exec_cmd("myshell screenshot"))
hl.bind("SUPER + S", hl.dsp.exec_cmd("myshell screenshot_region"))
hl.bind("SUPER + SHIFT + S", hl.dsp.exec_cmd("myshell screenshot_edit"))

hl.bind("SUPER + Grave", hl.dsp.exec_cmd("myshell menu"))
hl.bind("SUPER + CONTROL + A", hl.dsp.exec_cmd("myshell audio"))
hl.bind("SUPER + CONTROL + B", hl.dsp.exec_cmd("myshell bluetooth"))
hl.bind("SUPER + CONTROL + C", hl.dsp.exec_cmd("myshell cal"))
hl.bind("SUPER + CONTROL + M", hl.dsp.exec_cmd("myshell media"))
hl.bind("SUPER + CONTROL + N", hl.dsp.exec_cmd("myshell network"))
hl.bind("SUPER + CONTROL + T", hl.dsp.exec_cmd("myshell top"))

hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("myshell audio_up"), { repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("myshell audio_down"), { repeating = true })
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("myshell brightness_up"), { repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("myshell brightness_down"), { repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("myshell audio_mute"))

hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("myshell media_play"))
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("myshell media_next"))
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("myshell media_prev"))
hl.bind("XF86AudioMedia", hl.dsp.exec_cmd("myshell audio"))

--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

hl.workspace_rule({
	workspace = "10",
	monitor = "DP-3",
	default = true,
})

hl.window_rule({
	-- Ignore maximize requests from all apps. You'll probably like this.
	name = "suppress-maximize-events",
	match = { class = ".*" },

	suppress_event = "maximize",
})

hl.window_rule({
	-- Fix some dragging issues with XWayland
	name = "fix-xwayland-drags",
	match = {
		class = "^$",
		title = "^$",
		xwayland = true,
		float = true,
		fullscreen = false,
		pin = false,
	},

	no_focus = true,
})
